SELECT order_id, CAST(format_datetime(at_timezone(order_date, current_timezone()), 'yyyyMMdd') AS INTEGER) AS date_key, 'restaurant:client:' || CAST(client_id AS VARCHAR) AS client_key, 'restaurant:' || CAST(restaurant_id AS VARCHAR) AS restaurant_key, final_status AS status_code, order_date, cost, payment, payed_by_bonuses, bonus_for_visit FROM lake.stg.mongo_orders WHERE batch_id = '{{batch_id}}'
